const { app, pool } = await import('./index.js')

let token
test('catálogo reconciliado contém as 460 funções autenticadas',async()=>{
  const {moduleCatalog,slugify}=await import('../src/moduleCatalog.js')
  const expected={'Fiéis e Cadastros':30,'Dízimos e Ofertas':14,Financeiro:82,Batismo:22,Catequese:26,Crisma:23,Eucaristia:16,Matrimônio:39,Campanhas:10,'Agendas e Cursos':27,Almoxarifado:23,Cemitério:7,Contábil:61,Patrimônio:26,'Gestão Social':20,ParóquiaNet:8,Conectividade:4,'Partilha Fraterna':5,Configurações:17}
  const counts=Object.fromEntries(Object.entries(moduleCatalog).map(([name,module])=>[name,module.groups.flatMap(group=>group.items).length]))
  assert.deepEqual(counts,expected)
  assert.equal(Object.values(counts).reduce((sum,count)=>sum+count,0),460)
  const routes=[]
  for(const module of Object.values(moduleCatalog)){const labels=module.groups.flatMap(group=>group.items),duplicates=labels.reduce((all,label)=>({...all,[label]:(all[label]||0)+1}),{});module.groups.forEach((group,groupIndex)=>group.items.forEach((label,itemIndex)=>routes.push(`${module.slug}/${duplicates[label]>1?`${slugify(label)}-${groupIndex+1}-${itemIndex+1}`:slugify(label)}`)))}
  assert.equal(new Set(routes).size,460)
})
