test('financeiro opera vales, cheques, repasses, recibos e orçamento',async()=>{
  const stamp=Date.now(),metadata=await request(app).get('/api/finance/metadata').set('Authorization',`Bearer ${token}`),people=await request(app).get('/api/people').set('Authorization',`Bearer ${token}`)
  assert.ok(metadata.body.accounts.length>=2)
  const [fromAccount,toAccount]=metadata.body.accounts
  const voucher=await request(app).post('/api/finance/vouchers').set('Authorization',`Bearer ${token}`).send({voucherType:'advance',personId:people.body.data[0].id,beneficiaryName:people.body.data[0].name,description:`Adiantamento QA ${stamp}`,amount:120,issuedOn:'2090-01-02',dueOn:'2090-01-31'})
  assert.equal(voucher.status,201)
  assert.ok(voucher.body.data.obligation_id)
  const check=await request(app).post('/api/finance/checks').set('Authorization',`Bearer ${token}`).send({accountId:fromAccount.id,checkNumber:`CH-${stamp}`,payee:'Fornecedor QA',description:'Material',amount:80,issuedOn:'2090-01-03',dueOn:'2090-01-04'})
  assert.equal(check.status,201)
  const cleared=await request(app).post(`/api/finance/checks/${check.body.data.id}/clear`).set('Authorization',`Bearer ${token}`).send({clearedOn:'2090-01-04'})
  assert.equal(cleared.body.data.status,'cleared')
  assert.ok(cleared.body.data.financial_transaction_id)
  const transfer=await request(app).post('/api/finance/transfers').set('Authorization',`Bearer ${token}`).send({fromAccountId:fromAccount.id,toAccountId:toAccount.id,amount:50,transferredOn:'2090-01-05',description:'Reforço de caixa',reference:`TR-${stamp}`})
  assert.equal(transfer.status,201)
  assert.ok(transfer.body.data.outgoing_transaction_id)
  assert.ok(transfer.body.data.incoming_transaction_id)
  const receipt=await request(app).post('/api/finance/receipts').set('Authorization',`Bearer ${token}`).send({receiptType:'rpa',accountId:fromAccount.id,recipientName:'Prestador QA',recipientDocument:'12345678900',description:'Serviço eventual',grossAmount:200,deductionAmount:20,issuedOn:'2090-01-06',paymentMethod:'pix'})
  assert.equal(receipt.status,201)
  assert.equal(Number(receipt.body.data.net_amount),180)
  const structure=await request(app).post('/api/finance/budget-structures').set('Authorization',`Bearer ${token}`).send({code:`QA-${stamp}`,name:'Projeto pastoral QA',kind:'expense'})
  assert.equal(structure.status,201)
  const budget=await request(app).post('/api/finance/budgets').set('Authorization',`Bearer ${token}`).send({structureId:structure.body.data.id,year:2090,month:1,plannedAmount:1000})
  assert.equal(budget.status,201)
  const master=await request(app).post('/api/finance/master-data').set('Authorization',`Bearer ${token}`).send({dataType:'document_type',code:`DOC-${stamp}`,name:'Documento QA'})
  assert.equal(master.status,201)
  const overview=await request(app).get('/api/finance/operations?year=2090').set('Authorization',`Bearer ${token}`)
  assert.ok(overview.body.transfers.some(item=>item.id===transfer.body.data.id))
  assert.ok(overview.body.receipts.some(item=>item.id===receipt.body.data.id))
  assert.ok(overview.body.plans.some(item=>item.id===budget.body.data.id))
})

