test('campanha integra compromissos, recebimentos e despesas ao financeiro',async()=>{
  const people=await request(app).get('/api/people').set('Authorization',`Bearer ${token}`)
  const campaign=await request(app).post('/api/campaigns').set('Authorization',`Bearer ${token}`).send({name:`Campanha QA ${Date.now()}`,campaignType:'construction',startsOn:'2026-09-01',endsOn:'2026-12-31',targetAmount:10000,status:'active'})
  assert.equal(campaign.status,201)
  const pledge=await request(app).post(`/api/campaigns/${campaign.body.data.id}/pledges`).set('Authorization',`Bearer ${token}`).send({personId:people.body.data[0].id,amount:500,frequency:'once',pledgedOn:'2026-09-01',dueDate:'2026-09-30'})
  assert.equal(pledge.status,201)
  const donation=await request(app).post(`/api/campaigns/${campaign.body.data.id}/donations`).set('Authorization',`Bearer ${token}`).send({pledgeId:pledge.body.data.id,amount:500,receivedOn:'2026-09-10',paymentMethod:'pix'})
  assert.equal(donation.status,201)
  assert.ok(donation.body.data.financial_transaction_id)
  const expense=await request(app).post(`/api/campaigns/${campaign.body.data.id}/expenses`).set('Authorization',`Bearer ${token}`).send({description:'Material de divulgação',amount:75,occurredOn:'2026-09-11'})
  assert.equal(expense.status,201)
  const campaigns=await request(app).get('/api/campaigns').set('Authorization',`Bearer ${token}`)
  const updated=campaigns.body.data.find(item=>item.id===campaign.body.data.id)
  assert.equal(Number(updated.received_amount),500)
  assert.equal(Number(updated.expense_amount),75)
  const details=await request(app).get(`/api/campaigns/${campaign.body.data.id}/details`).set('Authorization',`Bearer ${token}`)
  assert.equal(details.body.pledges[0].status,'fulfilled')
})

test('contabilidade exige partidas balanceadas e produz balancete',async()=>{
  const accounts=await request(app).get('/api/accounting/accounts').set('Authorization',`Bearer ${token}`)
  const cash=accounts.body.data.find(item=>item.code==='1.1.01'),revenue=accounts.body.data.find(item=>item.code==='4.1.01')
  const invalid=await request(app).post('/api/accounting/entries').set('Authorization',`Bearer ${token}`).send({entryDate:'2027-01-10',memo:'Lançamento inválido',status:'posted',lines:[{accountId:cash.id,debit:100,credit:0},{accountId:revenue.id,debit:0,credit:90}]})
  assert.equal(invalid.status,400)
  const entry=await request(app).post('/api/accounting/entries').set('Authorization',`Bearer ${token}`).send({entryDate:'2027-01-10',memo:'Receita contábil de teste',status:'posted',lines:[{accountId:cash.id,debit:100,credit:0},{accountId:revenue.id,debit:0,credit:100}]})
  assert.equal(entry.status,201)
  const trial=await request(app).get('/api/accounting/trial-balance?from=2027-01-01&to=2027-12-31').set('Authorization',`Bearer ${token}`)
  const totalDebit=trial.body.data.reduce((sum,item)=>sum+Number(item.debit),0),totalCredit=trial.body.data.reduce((sum,item)=>sum+Number(item.credit),0)
  assert.equal(totalDebit,totalCredit)
  assert.ok(totalDebit>=100)
})

test('contabilidade mantém exercício, responsáveis, abertura, notas e demonstrações',async()=>{
  const year=2199,from=`${year}-01-01`,to=`${year}-12-31`
  const accounts=await request(app).get('/api/accounting/accounts').set('Authorization',`Bearer ${token}`)
  const cash=accounts.body.data.find(item=>item.code==='1.1.01'),equity=accounts.body.data.find(item=>item.code==='3')
  let exercise=await request(app).post('/api/accounting/exercises').set('Authorization',`Bearer ${token}`).send({year,startsOn:from,endsOn:to})
  if(exercise.status===409){const current=await request(app).get('/api/accounting/settings').set('Authorization',`Bearer ${token}`),existing=current.body.exercises.find(item=>item.year===year);exercise={body:{data:existing},status:200}}
  assert.ok([200,201].includes(exercise.status))
  const professional=await request(app).post('/api/accounting/professionals').set('Authorization',`Bearer ${token}`).send({role:'accountant',name:'Contabilista QA',document:'12345678900',registrationNumber:'CRC-QA',registrationState:'PA'})
  assert.equal(professional.status,201)
  for(const balance of [{accountId:cash.id,debit:500,credit:0},{accountId:equity.id,debit:0,credit:500}]){
    const response=await request(app).post('/api/accounting/opening-balances').set('Authorization',`Bearer ${token}`).send({exerciseId:exercise.body.data.id,...balance})
    assert.equal(response.status,201)
  }
  const disclosure=await request(app).post('/api/accounting/disclosures').set('Authorization',`Bearer ${token}`).send({exerciseId:exercise.body.data.id,statementType:'balance_sheet',title:'Critérios contábeis',content:'Demonstrações elaboradas pelo regime de competência.'})
  assert.equal(disclosure.status,201)
  const balanceSheet=await request(app).get(`/api/accounting/statements/balance-sheet?from=${from}&to=${to}`).set('Authorization',`Bearer ${token}`)
  assert.equal(balanceSheet.status,200)
  assert.ok(Number(balanceSheet.body.summary.asset)>=500)
  assert.ok(Number(balanceSheet.body.summary.equity)>=500)
  for(const type of ['general-ledger','cash-book','income-statement','cash-flow','equity-changes']){
    const statement=await request(app).get(`/api/accounting/statements/${type}?from=${from}&to=${to}`).set('Authorization',`Bearer ${token}`)
    assert.equal(statement.status,200)
  }
  const settings=await request(app).get('/api/accounting/settings').set('Authorization',`Bearer ${token}`)
  assert.ok(settings.body.professionals.some(item=>item.name==='Contabilista QA'))
  assert.ok(settings.body.disclosures.some(item=>item.title==='Critérios contábeis'))
  assert.equal(settings.body.openingBalances.filter(item=>item.exercise_id===exercise.body.data.id).reduce((sum,item)=>sum+Number(item.debit),0),500)
  assert.equal(settings.body.openingBalances.filter(item=>item.exercise_id===exercise.body.data.id).reduce((sum,item)=>sum+Number(item.credit),0),500)
})

