  assert.equal(donor.status,201)
  const product=await request(app).post('/api/social/products').set('Authorization',`Bearer ${token}`).send({productTypeId:center.body.productTypes[0].id,code:`SOC-${stamp}`,name:'Arroz social QA',unit:'kg',minimumStock:2})
  assert.equal(product.status,201)
  const entry=await request(app).post('/api/social/stock-movements').set('Authorization',`Bearer ${token}`).send({productId:product.body.data.id,kind:'entry',quantity:10,occurredOn:'2092-01-01',donorId:donor.body.data.id})
  assert.equal(entry.status,201)
  const kit=await request(app).post('/api/social/kits').set('Authorization',`Bearer ${token}`).send({code:`KIT-${stamp}`,name:'Cesta QA',items:[{productId:product.body.data.id,quantity:2}]})
  assert.equal(kit.status,201)
  const assembly=await request(app).post(`/api/social/kits/${kit.body.data.id}/assemble`).set('Authorization',`Bearer ${token}`).send({quantity:2,assembledOn:'2092-01-02'})
  assert.equal(assembly.status,201)
  const individual=await request(app).post('/api/social/distributions').set('Authorization',`Bearer ${token}`).send({distributionType:'individual',householdId:households.body.data[0].id,kitId:kit.body.data.id,quantity:1,distributedOn:'2092-01-03',deliveredBy:'Equipe QA'})
  assert.equal(individual.status,201)
  const community=await request(app).post('/api/social/distributions').set('Authorization',`Bearer ${token}`).send({distributionType:'community',communityName:'Comunidade QA',productId:product.body.data.id,quantity:2,distributedOn:'2092-01-04'})
  assert.equal(community.status,201)
  const schedule=await request(app).post('/api/social/schedules').set('Authorization',`Bearer ${token}`).send({title:'Mutirão social QA',scheduledFor:'2092-02-01T12:00:00.000Z',location:'Salão paroquial',audience:'Famílias'})
