test('catequese emite certidão, registra livro e oblação e exporta ao sacramento',async()=>{
  const stamp=Date.now(),people=await request(app).get('/api/people').set('Authorization',`Bearer ${token}`)
  const metadata=await request(app).get('/api/catechesis/metadata').set('Authorization',`Bearer ${token}`)
  const stage=metadata.body.stages.find(item=>item.sacrament_type==='eucharist')
  const group=await request(app).post('/api/catechesis/groups').set('Authorization',`Bearer ${token}`).send({name:`Eucaristia documental ${stamp}`,stageId:stage.id,capacity:10})
  assert.equal(group.status,201)
  const enrollment=await request(app).post(`/api/catechesis/groups/${group.body.data.id}/enrollments`).set('Authorization',`Bearer ${token}`).send({personId:people.body.data[0].id,enrolledAt:'2094-01-01'})
  assert.equal(enrollment.status,201)
  const completed=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/complete`).set('Authorization',`Bearer ${token}`).send({completedAt:'2094-12-01'})
  assert.equal(completed.status,200)
  const certificateRequest=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/certificate-request`).set('Authorization',`Bearer ${token}`).send({requestedOn:'2094-12-02',purpose:'Arquivo familiar'})
  assert.equal(certificateRequest.status,201)
  const certificate=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/certificate`).set('Authorization',`Bearer ${token}`).send({requestId:certificateRequest.body.data.id})
  assert.equal(certificate.status,201)
  assert.ok(certificate.body.data.validation_code)
  const book=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/book-entry`).set('Authorization',`Bearer ${token}`).send({book:`CAT-${stamp}`,page:'12',entryNumber:'34',recordedOn:'2094-12-02'})
  assert.equal(book.status,201)
  const fee=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/fees`).set('Authorization',`Bearer ${token}`).send({description:'Material catequético',amount:35,dueOn:'2094-12-10'})
  assert.equal(fee.status,201)
  const paid=await request(app).post(`/api/catechesis/fees/${fee.body.data.id}/pay`).set('Authorization',`Bearer ${token}`).send({paidOn:'2094-12-03',paymentMethod:'Dinheiro'})
  assert.equal(paid.status,200)
  assert.ok(paid.body.receipt.startsWith('CAT-REC-'))
  const exported=await request(app).post(`/api/catechesis/enrollments/${enrollment.body.data.id}/export-sacrament`).set('Authorization',`Bearer ${token}`).send({requestedOn:'2094-12-04'})
  assert.equal(exported.status,201)
  assert.equal(exported.body.data.sacrament_type,'eucharist')
  const operations=await request(app).get(`/api/catechesis/operations?groupId=${group.body.data.id}`).set('Authorization',`Bearer ${token}`)
  assert.ok(operations.body.certificateRequests.some(item=>item.id===certificateRequest.body.data.id&&item.status==='issued'))
  assert.ok(operations.body.bookEntries.some(item=>item.id===book.body.data.id))
  assert.equal(operations.body.fees.find(item=>item.id===fee.body.data.id).status,'paid')
  const second=await request(app).post(`/api/catechesis/groups/${group.body.data.id}/enrollments`).set('Authorization',`Bearer ${token}`).send({personId:people.body.data[1].id,enrolledAt:'2094-01-01'})
  const cancelled=await request(app).post(`/api/catechesis/enrollments/${second.body.data.id}/cancel`).set('Authorization',`Bearer ${token}`).send({reason:'Mudança de paróquia'})
  assert.equal(cancelled.status,200)
  assert.equal(cancelled.body.data.status,'cancelled')
})

